-- Phase 55: planning and performance management. Metric formulas remain in analytics_metric_catalog.
alter table public.plans add column if not exists performance_management_enabled boolean not null default true,add column if not exists goals_enabled boolean not null default true,add column if not exists okr_enabled boolean not null default false,add column if not exists budget_management_enabled boolean not null default false,add column if not exists scorecards_enabled boolean not null default false;
alter table public.store_feature_flags add column if not exists performance_management_enabled boolean not null default true,add column if not exists goals_enabled boolean not null default true,add column if not exists okr_enabled boolean not null default false,add column if not exists budget_management_enabled boolean not null default false,add column if not exists scorecards_enabled boolean not null default false;
create table public.performance_goals(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,parent_goal_id uuid references public.performance_goals(id) on delete restrict,name text not null,description text,metric_id text not null references public.analytics_metric_catalog(metric_key),scope_type text not null check(scope_type in('organization','brand','region','cluster','store','team','channel','product_category','custom_supported_scope')),scope_id text,owner_user_id uuid references auth.users(id) on delete set null,period_type text not null check(period_type in('daily','weekly','monthly','quarterly','annual','custom')),period_start date not null,period_end date not null,target_value numeric,target_direction text not null check(target_direction in('increase','decrease','maintain_range')),target_min numeric,target_max numeric,baseline_value numeric,baseline_source text,thresholds jsonb not null default '{"on_track":0.98,"at_risk":0.90}',status text not null default 'draft' check(status in('draft','active','achieved','missed','cancelled','archived')),weight numeric check(weight between 0 and 100),version integer not null default 1,financial_sensitive boolean not null default false,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(period_end>period_start),check((target_direction='maintain_range' and target_min is not null and target_max is not null and target_min<=target_max) or (target_direction<>'maintain_range' and target_value is not null)));
create table public.goal_versions(id uuid primary key default gen_random_uuid(),goal_id uuid not null references public.performance_goals(id) on delete restrict,version integer not null,target_value numeric,target_min numeric,target_max numeric,period_start date not null,period_end date not null,scope_type text not null,scope_id text,baseline_value numeric,baseline_source text,changed_by uuid not null references auth.users(id),changed_at timestamptz not null default now(),reason text not null,unique(goal_id,version));
create table public.goal_progress_snapshots(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,goal_id uuid not null references public.performance_goals(id) on delete restrict,goal_version integer not null,snapshot_at timestamptz not null,actual_value numeric,progress numeric,time_progress numeric,health text not null check(health in('on_track','at_risk','off_track','achieved','no_data')),forecast_value numeric,forecast_source text check(forecast_source in('predictive_model','run_rate','manual','none')),gap_value numeric,gap_percent numeric,required_pace numeric,data_as_of timestamptz,source_freshness jsonb not null default '{}',calculation_trace jsonb not null default '{}',unique(goal_id,goal_version,snapshot_at));
create table public.goal_allocations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,parent_goal_id uuid not null references public.performance_goals(id) on delete restrict,child_goal_id uuid references public.performance_goals(id) on delete restrict,child_scope_type text not null,child_scope_id text not null,method text not null check(method in('manual','equal','historical_share','capacity_weighted','custom')),allocated_value numeric not null,share numeric not null check(share>=0 and share<=1),preview_snapshot jsonb not null default '{}',confirmed_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.goal_adjustment_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,goal_id uuid not null references public.performance_goals(id) on delete restrict,proposed_target numeric,proposed_min numeric,proposed_max numeric,reason text not null,requested_by uuid not null references auth.users(id),status text not null default 'pending' check(status in('pending','approved','rejected')),reviewer uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now());
create table public.performance_scorecards(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,scope_type text not null,scope_id text,period_type text not null,owner_user_id uuid references auth.users(id),status text not null default 'draft' check(status in('draft','active','archived')),score_enabled boolean not null default false,formula_label text not null default 'weighted transparent score',created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.performance_scorecard_items(id uuid primary key default gen_random_uuid(),scorecard_id uuid not null references public.performance_scorecards(id) on delete cascade,goal_id uuid references public.performance_goals(id) on delete set null,metric_id text not null references public.analytics_metric_catalog(metric_key),target numeric,weight numeric not null default 1 check(weight>=0),display_order integer not null default 0,created_at timestamptz not null default now());
create table public.performance_scorecard_results(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,scorecard_id uuid not null references public.performance_scorecards(id) on delete restrict,period_start date not null,period_end date not null,health text not null check(health in('green','yellow','red','no_data')),score numeric,contributions jsonb not null default '[]',formula text,data_as_of timestamptz,created_at timestamptz not null default now());
create table public.objectives(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,title text not null,description text,scope_type text not null,scope_id text,owner_user_id uuid references auth.users(id),period_start date not null,period_end date not null,status text not null default 'draft' check(status in('draft','active','completed','cancelled','archived')),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.key_results(id uuid primary key default gen_random_uuid(),objective_id uuid not null references public.objectives(id) on delete cascade,title text not null,result_type text not null check(result_type in('metric_based','milestone_based')),metric_id text references public.analytics_metric_catalog(metric_key),target_value numeric,current_value numeric,progress_source text not null check(progress_source in('semantic_metric','internal_task','manual_milestone')),owner_user_id uuid references auth.users(id),weight numeric check(weight>=0),status text not null default 'active' check(status in('active','achieved','blocked','cancelled')),updated_at timestamptz not null default now(),check((result_type='metric_based' and metric_id is not null and progress_source='semantic_metric') or result_type='milestone_based'));
create table public.okr_checkins(id uuid primary key default gen_random_uuid(),objective_id uuid not null references public.objectives(id) on delete cascade,key_result_id uuid references public.key_results(id) on delete cascade,author_user_id uuid not null references auth.users(id),confidence text not null check(confidence in('low','medium','high')),note text,blockers text,created_at timestamptz not null default now());
create table public.operational_budgets(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,scope_type text not null,scope_id text,fiscal_period text not null,category text not null check(category in('revenue','food_cost','labor','marketing','maintenance','utilities','delivery','software','other')),category_behavior text not null check(category_behavior in('revenue_like','expense_like','neutral')),planned_value numeric not null,scenario text not null check(scenario in('base','conservative','aggressive','custom')),version integer not null default 1,status text not null default 'draft' check(status in('draft','approved','locked','superseded','archived')),owner_user_id uuid references auth.users(id),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(organization_id,scope_type,scope_id,fiscal_period,category,scenario,version));
create table public.budget_versions(id uuid primary key default gen_random_uuid(),budget_id uuid not null references public.operational_budgets(id) on delete restrict,version integer not null,planned_value numeric not null,scenario text not null,status text not null,reason text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(budget_id,version));
create table public.budget_actual_snapshots(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,budget_id uuid not null references public.operational_budgets(id) on delete restrict,budget_version integer not null,snapshot_at timestamptz not null,actual_value numeric not null,variance numeric not null,variance_percent numeric,favorable boolean,data_as_of timestamptz not null,source text not null default 'financial_semantic_layer');
create table public.performance_forecasts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,goal_id uuid references public.performance_goals(id) on delete cascade,budget_id uuid references public.operational_budgets(id) on delete cascade,forecast_type text not null check(forecast_type in('system_generated','manager_override','consensus')),value numeric not null,confidence text check(confidence in('low','medium','high')),source_run_id text,reason text,author_user_id uuid references auth.users(id),approved_by uuid references auth.users(id),created_at timestamptz not null default now(),check(forecast_type='system_generated' or reason is not null));
create table public.performance_action_plans(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,goal_id uuid references public.performance_goals(id) on delete cascade,objective_id uuid references public.objectives(id) on delete cascade,title text not null,owner_user_id uuid references auth.users(id),due_at timestamptz,status text not null default 'draft' check(status in('draft','active','completed','cancelled')),source text not null default 'manager',created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),check(goal_id is not null or objective_id is not null));
create table public.performance_action_plan_tasks(action_plan_id uuid not null references public.performance_action_plans(id) on delete cascade,internal_task_id uuid not null references public.internal_tasks(id) on delete restrict,primary key(action_plan_id,internal_task_id));
create table public.performance_reviews(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,scope_type text not null,scope_id text,period_start date not null,period_end date not null,review_type text not null check(review_type in('weekly_business_review','monthly_business_review','custom')),status text not null default 'draft' check(status in('draft','published','archived')),owner_user_id uuid references auth.users(id),summary text,sections jsonb not null default '{}',report_ids uuid[] not null default '{}',created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.performance_goal_templates(id text primary key,name text not null,description text not null,metric_id text not null references public.analytics_metric_catalog(metric_key),target_direction text not null,default_scope text not null,active boolean not null default true);
create table public.performance_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,actor_user_id uuid references auth.users(id),entity_type text not null,entity_id text not null,action text not null,reason text,before_state jsonb,after_state jsonb,created_at timestamptz not null default now());
create table public.performance_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,job_type text not null check(job_type in('goal_progress','budget_variance','forecast_refresh','scorecard_calculation')),entity_id uuid,status text not null default 'pending' check(status in('pending','running','completed','failed')),priority smallint not null default 50,attempts integer not null default 0,available_at timestamptz not null default now(),last_error text,created_at timestamptz not null default now());
create table public.performance_metrics_hourly(organization_id uuid not null references public.organizations(id) on delete cascade,bucket_at timestamptz not null,goal_progress_jobs bigint not null default 0,goal_progress_failures bigint not null default 0,budget_variance_jobs bigint not null default 0,forecast_refresh_latency_ms bigint not null default 0,scorecard_calculation_duration_ms bigint not null default 0,primary key(organization_id,bucket_at));
create index performance_goals_scope_idx on public.performance_goals(organization_id,scope_type,scope_id,status,period_start,period_end);create index performance_goals_owner_idx on public.performance_goals(organization_id,owner_user_id,status);create index goal_snapshots_goal_idx on public.goal_progress_snapshots(goal_id,snapshot_at desc);create index performance_jobs_due_idx on public.performance_jobs(status,priority desc,available_at) where status='pending';create index budgets_scope_idx on public.operational_budgets(organization_id,scope_type,scope_id,fiscal_period,status);create index objectives_scope_idx on public.objectives(organization_id,scope_type,scope_id,status);
insert into public.performance_goal_templates(id,name,description,metric_id,target_direction,default_scope) values('revenue-growth','Crescimento de receita','Acompanhar receita certificada no período.','revenue','increase','store'),('margin-improvement','Melhorar margem','Acompanhar margem oficial.','gross_margin','increase','store'),('reduce-prep-time','Reduzir tempo de preparo','Diminuir tempo médio certificado.','prep_time','decrease','store'),('reduce-waste','Reduzir desperdício','Diminuir custo de perdas.','waste_cost','decrease','store'),('improve-csat','Melhorar CSAT','Aumentar satisfação.','csat','increase','store'),('delivery-time','Melhorar entrega','Reduzir tempo médio de entrega.','delivery_time','decrease','store'),('stock-availability','Melhorar disponibilidade','Reduzir rupturas.','stockout_rate','decrease','store') on conflict(id) do update set name=excluded.name,description=excluded.description,metric_id=excluded.metric_id,target_direction=excluded.target_direction;
