insert into public.workspace_widget_registry(id,title,description,category,widget_type,size_options,required_permissions,supported_scopes,data_source,refresh_strategy,configuration_schema,default_settings,route,display_safe,sensitive) values('goals_progress','Progresso das metas','Metas no ritmo, em risco e atingidas.','performance','progress','["medium","large"]','{performance:view}','{store,network}','performance:goals','1m','{}','{}','/painel/metas',true,false),('budget_vs_actual','Budget vs Actual','Orçamento gerencial versus realizado.','performance','metric_card','["medium","large"]','{performance:view_financial_targets}','{store,network}','performance:budget','5m','{}','{}','/painel/metas?tab=budget',false,true),('okr_progress','Progresso de OKRs','Objetivos e KRs atuais.','performance','progress','["medium","large"]','{performance:view}','{store,network}','performance:okr','5m','{}','{}','/painel/metas?tab=okrs',true,false),('forecast_vs_target','Forecast vs Meta','Projeção atual versus objetivo.','performance','trend_chart','["medium","large"]','{performance:view}','{store,network}','performance:forecast','5m','{}','{}','/painel/metas?tab=forecast',true,false),('scorecard','Scorecard','Saúde operacional transparente.','performance','status_list','["medium","large"]','{performance:view}','{store,network}','performance:scorecard','5m','{}','{}','/painel/metas?tab=scorecards',true,false) on conflict(id) do update set title=excluded.title,description=excluded.description,required_permissions=excluded.required_permissions,data_source=excluded.data_source,route=excluded.route;
insert into public.search_navigation_registry(id,title,route,keywords,module,required_permission,icon,position) values('performance-management','Metas e Performance','/painel/metas',array['metas','okr','budget','scorecard','performance'],'performance','performance:view','◎',66) on conflict(id) do update set title=excluded.title,route=excluded.route,keywords=excluded.keywords,required_permission=excluded.required_permission;
insert into public.automation_event_registry(event_name,schema_version,module,description,payload_schema,allowed_fields,sensitivity) values('goal.at_risk',1,'performance','Meta entrou em risco','{"type":"object"}','{goal.id,goal.health,goal.gap,store.id}','sensitive'),('goal.off_track',1,'performance','Meta saiu do ritmo','{"type":"object"}','{goal.id,goal.health,goal.gap,store.id}','sensitive'),('budget.variance_exceeded',1,'performance','Variação orçamentária excedida','{"type":"object"}','{budget.id,budget.variance,store.id}','restricted'),('okr.blocked',1,'performance','OKR bloqueado','{"type":"object"}','{objective.id,key_result.id,store.id}','normal') on conflict(event_name,schema_version) do nothing;
insert into public.notification_source_registry(id,event_type,category,source_type,title_template,summary_template,priority_rules,allowed_actions,default_recipient_rules,dedup_strategy,grouping_strategy,expiration_strategy,sensitivity) values('goal-at-risk','goal.at_risk','performance','performance_goal','Meta em risco','A projeção está abaixo do ritmo configurado.','{"default":"high"}','["open","acknowledge","create_task"]','["goal_owner"]','{"key":"goal:health:owner"}','{"key":"goal"}','{"expires_hours":168}','sensitive'),('goal-achieved','goal.achieved','performance','performance_goal','Meta atingida','A meta atingiu o valor configurado.','{"default":"info"}','["open","acknowledge"]','["goal_owner"]','{"key":"goal:achieved:owner"}','{"key":"goal"}','{"expires_hours":168}','normal'),('budget-exceeded','budget.variance_exceeded','performance','operational_budget','Orçamento excedido','A variação ultrapassou o limite configurado.','{"default":"high"}','["open","acknowledge","create_task"]','["budget_owner"]','{"key":"budget:period:owner"}','{"key":"budget"}','{"expires_hours":168}','confidential') on conflict(event_type) do nothing;
do $$ declare t text;begin foreach t in array array['performance_goals','goal_versions','goal_progress_snapshots','goal_allocations','goal_adjustment_requests','performance_scorecards','performance_scorecard_items','performance_scorecard_results','objectives','key_results','okr_checkins','operational_budgets','budget_versions','budget_actual_snapshots','performance_forecasts','performance_action_plans','performance_action_plan_tasks','performance_reviews','performance_goal_templates','performance_audit_events','performance_jobs','performance_metrics_hourly'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)',t||'_service_only',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
grant select on public.performance_goal_templates to authenticated;create policy performance_goal_templates_read on public.performance_goal_templates for select to authenticated using(active);
-- Published goals and locked budgets are immutable in application flows; changes create version/audit rows.
